function deliveryFee(total, isPremium) {
  let fee = 5;
  if (isPremium) {
    fee = 0;
  }
  if (total >= 50) {
    fee = 0;
  }
  return fee;
}

const testInputs = [
  { total: 60, isPremium: true, expected: 0 },
  { total: 20, isPremium: false, expected: 5 },
];
